<?php
require_once 'sacco_common.php';
$sid=(int)($_GET['sacco_id']??0);$type=$_GET['type']??'';$from=$_GET['from']??'';$to=$_GET['to']??'';$qtext=trim($_GET['q']??'');
$where=[];$params=[];$bind='';
if($sid){$where[]='s.sacco_id=?';$params[]=$sid;$bind.='i';}
$valid=['contribution','withdrawal','opening_balance','adjustment_credit','adjustment_debit'];
if(in_array($type,$valid,true)){$where[]='t.transaction_type=?';$params[]=$type;$bind.='s';}
if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]='t.transaction_date>=?';$params[]=$from;$bind.='s';}
if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]='t.transaction_date<=?';$params[]=$to;$bind.='s';}
if($qtext!==''){$where[]="(e.first_name LIKE ? OR e.last_name LIKE ? OR s.sacco_name LIKE ? OR t.reference_number LIKE ?)";$v='%'.$qtext.'%';array_push($params,$v,$v,$v,$v);$bind.='ssss';}
$sql="SELECT t.*,m.sacco_member_id,s.sacco_name,COALESCE(NULLIF(TRIM(CONCAT(e.first_name,' ',e.last_name)),''),u.email,CONCAT('User #',u.user_id)) full_name FROM hr_sacco_transactions t JOIN hr_sacco_members m ON m.sacco_member_id=t.sacco_member_id JOIN hr_saccos s ON s.sacco_id=m.sacco_id JOIN users u ON u.user_id=m.user_id LEFT JOIN employees e ON e.employee_id=u.employee_id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY t.transaction_date DESC,t.transaction_id DESC LIMIT 1000";
$stmt=$conn->prepare($sql);if($bind)$stmt->bind_param($bind,...$params);$stmt->execute();$rows=$stmt->get_result();
$saccos=$conn->query("SELECT sacco_id,sacco_name FROM hr_saccos ORDER BY sacco_name");
$sum=$conn->query("SELECT COALESCE(SUM(CASE WHEN transaction_type='contribution' THEN amount ELSE 0 END),0) contributions,COALESCE(SUM(CASE WHEN transaction_type='withdrawal' THEN amount ELSE 0 END),0) withdrawals FROM hr_sacco_transactions")->fetch_assoc();
require_once 'navbar.php';
?>
<main class="ml-64 p-6 max-w-7xl mx-auto"><div class="flex justify-between flex-wrap gap-3 mb-6"><div><h1 class="text-2xl font-bold">SACCO Transaction History</h1><p class="text-sm text-gray-500">Filter contributions, withdrawals and adjustments.</p></div><a href="record_sacco_contribution.php" class="bg-blue-600 text-white px-4 py-2 rounded-lg">+ Record Transaction</a></div>
<div class="grid sm:grid-cols-2 gap-4 mb-5"><div class="bg-white border rounded-xl p-4">Total contributions <b class="block text-xl text-green-700">KSh <?=sm($sum['contributions'])?></b></div><div class="bg-white border rounded-xl p-4">Total withdrawals <b class="block text-xl text-orange-600">KSh <?=sm($sum['withdrawals'])?></b></div></div>
<form method="get" class="bg-white border rounded-xl p-4 mb-5 grid md:grid-cols-6 gap-3"><select name="sacco_id" class="border rounded p-2"><option value="0">All SACCOs</option><?php while($s=$saccos->fetch_assoc()):?><option value="<?=$s['sacco_id']?>" <?=$sid===$s['sacco_id']?'selected':''?>><?=se($s['sacco_name'])?></option><?php endwhile;?></select><select name="type" class="border rounded p-2"><option value="">All types</option><?php foreach($valid as $v):?><option value="<?=$v?>" <?=$type===$v?'selected':''?>><?=se(sacco_type_label($v))?></option><?php endforeach;?></select><input type="date" name="from" value="<?=se($from)?>" class="border rounded p-2"><input type="date" name="to" value="<?=se($to)?>" class="border rounded p-2"><input name="q" value="<?=se($qtext)?>" placeholder="Employee / reference" class="border rounded p-2"><button class="bg-gray-800 text-white rounded p-2">Filter</button></form>
<div class="bg-white border rounded-xl overflow-x-auto"><table class="w-full text-sm"><thead class="bg-gray-100"><tr><th class="p-3 text-left">Date</th><th class="p-3 text-left">Employee</th><th class="p-3 text-left">SACCO</th><th class="p-3 text-left">Type / Month</th><th class="p-3 text-left">Method / Ref</th><th class="p-3 text-right">Amount</th><th class="p-3">Statement</th></tr></thead><tbody>
<?php if($rows->num_rows):while($r=$rows->fetch_assoc()):?><tr class="border-t"><td class="p-3"><?=se($r['transaction_date'])?></td><td class="p-3"><?=se($r['full_name'])?></td><td class="p-3"><?=se($r['sacco_name'])?></td><td class="p-3"><?=se(sacco_type_label($r['transaction_type']))?><div class="text-xs text-gray-500"><?=$r['contribution_month']?se(date('M Y',strtotime($r['contribution_month']))):''?></div></td><td class="p-3"><?=se($r['payment_method'])?><div class="text-xs text-gray-500"><?=se($r['reference_number'])?></div></td><td class="p-3 text-right font-semibold"><?=sm($r['amount'])?></td><td class="p-3 text-center"><a class="text-blue-600 underline" href="sacco_member_statement.php?id=<?=$r['sacco_member_id']?>">View</a></td></tr><?php endwhile;else:?><tr><td colspan="7" class="p-8 text-center text-gray-500">No transactions found.</td></tr><?php endif;?></tbody></table><p class="p-3 text-xs text-gray-500">Maximum 1,000 rows per result. Apply date filters for longer histories.</p></div></main>
